def highlight_differences(list1, list2):
    max_len = max(len(list1), len(list2))
    list1 = list1 + [' '] * (max_len - len(list1))
    list2 = list2 + [' '] * (max_len - len(list2))
    
    result = []
    in_difference = False 
    
    for char1, char2 in zip(list1, list2):
        if char1 == char2:
            if in_difference:
                result.append(']') 
                in_difference = False
            result.append(' ')  
        else:
            if not in_difference:
                result.append('[')  
                in_difference = True
            result.append(f"{char1}/{char2}") 

    if in_difference:
        result.append(']')

    return ''.join(result)

output = highlight_differences(a, b)
print(output)